def findString(N: int, K: int) -> str:
    def dfs(node):
        for i in range(K):
            edge = node + str(i)
            if edge not in visited:
                visited.add(edge)
                dfs(edge[1:])
                result.append(str(i))

    visited = set()
    result = []
    start_node = '0' * (N - 1)
    dfs(start_node)
    return ''.join(result) + start_node
